import{_ as e,c as i,o as s,ag as o}from"./chunks/framework.ymCRTBvy.js";const u=JSON.parse('{"title":"9.2_设置fromValue、toValue或byValue","description":"","frontmatter":{},"headers":[],"relativePath":"uikit/uikit_animation/9.2_设置fromValue、toValue或byValue.md","filePath":"uikit/uikit_animation/9.2_设置fromValue、toValue或byValue.md"}'),l={name:"uikit/uikit_animation/9.2_设置fromValue、toValue或byValue.md"};function t(n,a,d,c,r,h){return s(),i("div",null,a[0]||(a[0]=[o('<h1 id="_9-2-设置fromvalue、tovalue或byvalue" tabindex="-1">9.2_设置fromValue、toValue或byValue <a class="header-anchor" href="#_9-2-设置fromvalue、tovalue或byvalue" aria-label="Permalink to &quot;9.2_设置fromValue、toValue或byValue&quot;">​</a></h1><h2 id="动画的起点与终点-fromvalue-和-tovalue" tabindex="-1">动画的起点与终点：<code>fromValue</code> 和 <code>toValue</code> <a class="header-anchor" href="#动画的起点与终点-fromvalue-和-tovalue" aria-label="Permalink to &quot;动画的起点与终点：`fromValue` 和 `toValue`&quot;">​</a></h2><p>在 <code>CABasicAnimation</code> 中，<code>fromValue</code> 和 <code>toValue</code> 是定义动画关键状态的核心属性。它们分别代表了动画属性的起始值和结束值。想象一下，你正在为视图的透明度设置动画，<code>fromValue</code> 可以是 <code>0.0</code>（完全透明），而 <code>toValue</code> 可以是 <code>1.0</code>（完全不透明）。✨</p><p>当你设置这两个值时，系统会自动计算中间帧，让动画平滑地从 <code>fromValue</code> 过渡到 <code>toValue</code>。这就像电影制作中的关键帧，你只需要定义开始和结束，中间的精彩过程就由系统帮你完成！</p><h3 id="如何使用-fromvalue-和-tovalue" tabindex="-1">如何使用 <code>fromValue</code> 和 <code>toValue</code> <a class="header-anchor" href="#如何使用-fromvalue-和-tovalue" aria-label="Permalink to &quot;如何使用 `fromValue` 和 `toValue`&quot;">​</a></h3><p>使用 <code>fromValue</code> 和 <code>toValue</code> 非常直观。你需要创建一个 <code>CABasicAnimation</code> 实例，并指定你想要动画的 <code>keyPath</code>。例如，如果你想改变视图的 <code>opacity</code>（不透明度），<code>keyPath</code> 就是 <code>&quot;opacity&quot;</code>。</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> basicAnimation </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> CABasicAnimation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">keyPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;opacity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">basicAnimation.fromValue </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 动画开始时完全透明</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">basicAnimation.toValue </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 动画结束时完全不透明</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">basicAnimation.duration </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 动画持续2秒</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这段代码会创建一个从完全透明到完全不透明的动画，持续 2 秒。是不是超级简单？🚀</p><h2 id="增量动画的魔力-byvalue" tabindex="-1">增量动画的魔力：<code>byValue</code> <a class="header-anchor" href="#增量动画的魔力-byvalue" aria-label="Permalink to &quot;增量动画的魔力：`byValue`&quot;">​</a></h2><p>除了 <code>fromValue</code> 和 <code>toValue</code>，<code>CABasicAnimation</code> 还提供了一个强大的属性：<code>byValue</code>。<code>byValue</code> 用于定义动画属性的增量。这意味着动画会从当前值开始，增加或减少 <code>byValue</code> 指定的量。</p><p>例如，如果你想让一个视图向右移动 100 个点，你可以设置 <code>byValue</code> 为 <code>100</code>。系统会获取视图当前的 <code>position.x</code> 值，然后在此基础上增加 100。这对于实现相对位移的动画非常有用。</p><h3 id="byvalue-的应用场景" tabindex="-1"><code>byValue</code> 的应用场景 <a class="header-anchor" href="#byvalue-的应用场景" aria-label="Permalink to &quot;`byValue` 的应用场景&quot;">​</a></h3><p><code>byValue</code> 在很多场景下都非常实用，特别是当你不需要明确知道动画的起始值时。比如，你可能想让一个按钮每次点击后都稍微放大一点，而不管它当前的大小是多少。</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> scaleAnimation </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> CABasicAnimation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">keyPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;transform.scale&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scaleAnimation.byValue </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.2</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 在当前大小基础上放大20%</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scaleAnimation.duration </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scaleAnimation.autoreverses </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 动画结束后反向执行</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这段代码会让视图在当前大小的基础上放大 20%，然后反向缩小回原大小。这种增量动画的灵活性让你能够创建出更动态、更响应式的用户界面。📈</p><h2 id="fromvalue、tovalue-与-byvalue-的组合使用" tabindex="-1"><code>fromValue</code>、<code>toValue</code> 与 <code>byValue</code> 的组合使用 <a class="header-anchor" href="#fromvalue、tovalue-与-byvalue-的组合使用" aria-label="Permalink to &quot;`fromValue`、`toValue` 与 `byValue` 的组合使用&quot;">​</a></h2><p>理解这三个属性的组合使用方式至关重要。它们可以单独使用，也可以组合使用，以实现更复杂的动画效果。</p><ul><li><strong>只设置 <code>toValue</code></strong>: 如果只设置 <code>toValue</code>，动画会从属性的当前值开始，动画到 <code>toValue</code>。</li><li><strong>只设置 <code>fromValue</code></strong>: 如果只设置 <code>fromValue</code>，动画会从 <code>fromValue</code> 开始，动画到属性的当前值。</li><li><strong>设置 <code>fromValue</code> 和 <code>toValue</code></strong>: 这是最常见的用法，动画会从 <code>fromValue</code> 过渡到 <code>toValue</code>。</li><li><strong>设置 <code>fromValue</code> 和 <code>byValue</code></strong>: 动画会从 <code>fromValue</code> 开始，然后增加 <code>byValue</code> 的量。最终值是 <code>fromValue + byValue</code>。</li><li><strong>设置 <code>toValue</code> 和 <code>byValue</code></strong>: 动画会以 <code>toValue - byValue</code> 为起始值，然后增加 <code>byValue</code> 的量，最终达到 <code>toValue</code>。</li><li><strong>只设置 <code>byValue</code></strong>: 动画会从属性的当前值开始，增加 <code>byValue</code> 的量。</li></ul><p>掌握这些组合，你就能像魔术师一样，随心所欲地控制动画的每一个细节！🎩</p><h2 id="实践出真知-动手尝试" tabindex="-1">实践出真知：动手尝试！ <a class="header-anchor" href="#实践出真知-动手尝试" aria-label="Permalink to &quot;实践出真知：动手尝试！&quot;">​</a></h2><p>理论知识固然重要，但真正的精髓在于实践。我强烈建议你立即打开 Xcode，创建一个新的项目，并尝试使用 <code>fromValue</code>、<code>toValue</code> 和 <code>byValue</code> 来创建各种动画。</p><ol><li>尝试改变视图的 <code>position</code>，让它在屏幕上移动。</li><li>尝试改变视图的 <code>backgroundColor</code>，让它在不同颜色之间渐变。</li><li>尝试改变视图的 <code>transform.rotation.z</code>，让它旋转起来。</li></ol><p>你会发现，通过简单的几行代码，就能创造出令人惊叹的视觉效果。动画的世界充满了无限可能，而你正站在探索的起点！🚀 别忘了，每次尝试都是一次学习的机会，每一次成功都会让你对动画的理解更上一层楼！💪</p>',23)]))}const k=e(l,[["render",t]]);export{u as __pageData,k as default};
